    @RegisterExtension
    static WireMockExtension provider = WireMockExtension.newInstance().build();

    private final HttpPaymentGateway gateway =
            new HttpPaymentGateway(RestClient.builder().baseUrl(provider.baseUrl()).build());
    private final Money twelveEuros = new Money(new BigDecimal("12.50"), "eur");

    @Test
    void the_authorization_is_posted_as_json_to_the_authorizations_endpoint() {
        provider.stubFor(post(urlEqualTo("/v1/authorizations"))
                .willReturn(aResponse().withStatus(200).withHeader("Content-Type", "application/json")
                        .withBody("{\"status\":\"approved\"}")));

        gateway.authorize("ORD-7", twelveEuros);

        provider.verify(1, postRequestedFor(urlEqualTo("/v1/authorizations"))
                .withHeader("Content-Type", com.github.tomakehurst.wiremock.client.WireMock.containing("application/json"))
                .withRequestBody(equalToJson("{\"reference\":\"ORD-7\",\"amount\":12.50,\"currency\":\"EUR\"}")));
    }

    @Test
    void an_approved_answer_is_read_as_approved() {
        stubAnswer(200, "{\"status\":\"approved\"}");

        assertThat(gateway.authorize("ORD-7", twelveEuros)).isEqualTo(AuthorizationOutcome.APPROVED);
    }

    @Test
    void a_declined_answer_is_read_as_declined() {
        stubAnswer(200, "{\"status\":\"declined\"}");

        assertThat(gateway.authorize("ORD-7", twelveEuros)).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void an_unknown_status_is_never_read_as_approved() {
        stubAnswer(200, "{\"status\":\"pending\"}");

        assertThat(gateway.authorize("ORD-7", twelveEuros)).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void additional_fields_in_the_answer_are_tolerated() {
        stubAnswer(200, "{\"status\":\"approved\",\"id\":\"auth-1\",\"risk\":{\"score\":3}}");

        assertThat(gateway.authorize("ORD-7", twelveEuros)).isEqualTo(AuthorizationOutcome.APPROVED);
    }

    @Test
    void a_refusal_with_402_is_read_as_declined() {
        stubAnswer(402, "{\"error\":\"card_refused\"}");

        assertThat(gateway.authorize("ORD-7", twelveEuros)).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void a_request_the_provider_rejects_as_invalid_is_reported_as_a_failure() {
        stubAnswer(400, "{\"error\":\"invalid_currency\"}");

        assertThatThrownBy(() -> gateway.authorize("ORD-7", twelveEuros))
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("400");
    }

    @Test
    void a_provider_outage_is_reported_as_a_failure_not_as_a_decline() {
        stubAnswer(503, "");

        assertThatThrownBy(() -> gateway.authorize("ORD-7", twelveEuros))
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("503");
    }

    private void stubAnswer(int status, String body) {
        provider.stubFor(post(urlEqualTo("/v1/authorizations"))
                .willReturn(aResponse().withStatus(status).withHeader("Content-Type", "application/json")
                        .withBody(body)));
    }
}
